/* eslint-disable no-console */
/**
 * Assembles one self-contained production bundle: API + CMS + initial data.
 *
 *   npm run build:bundle          (from the repo root)
 *
 * Produces `dist-portal/`, which is everything needed to run the Portal on a
 * server with nothing installed but Node and a reachable MongoDB:
 *
 *   dist-portal/
 *     start.mjs              one entrypoint: wait for db -> initialize -> run both
 *     backend/dist           compiled NestJS API
 *     backend/node_modules   production dependencies only
 *     backend/seed-data      demo content captured from the CMS
 *     backend/seed-assets    the media that content references
 *     backend/restore-snapshot.mjs
 *     snapshot/              the live database and media, restored on first boot
 *     frontend/              Next.js standalone server, deps traced in
 *     bundle-info.json       node version and target architecture
 *     .env.example           what has to be set
 *     README.md              how to run it
 *
 * This is also the container's build step. `Dockerfile` copies this folder in
 * and compiles nothing, so building the image needs no compiler, no npm and no
 * `node_modules` inside it — the difference between an image build that needs a
 * gigabyte of RAM and one that is a file copy. It is the reason a ZimaBoard or
 * a free-tier instance can produce this image at all.
 *
 * The other half of the reason is that it can be built and *tested* on the
 * machine that produces it, which an image cannot be without a Docker daemon.
 */
import { execFileSync } from "node:child_process";
import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
  statSync,
  readdirSync,
} from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dirname, "..");
const OUT = join(ROOT, "dist-portal");

/*
 * The platform the bundle will RUN on, which is not necessarily the one
 * building it.
 *
 * `sharp` ships prebuilt binaries per platform, so a bundle assembled on
 * Windows carries `@img/sharp-win32-x64` and dies on a Linux host the moment
 * anything touches an image — an upload, or Next optimizing one. npm resolves
 * optional dependencies for `--os`/`--cpu` rather than the current machine,
 * which is exactly what cross-building needs.
 *
 * Override for an ARM server (a Raspberry Pi, AWS Graviton):
 *   TARGET_OS=linux TARGET_CPU=arm64 npm run build:bundle
 *
 * The CPU defaults to this machine's own when building *on* Linux, because
 * then the build host and the target are almost always the same box — an
 * arm64 server that hardcoded `x64` would assemble a bundle it cannot run, and
 * the failure would not appear until the first image was uploaded. Building
 * from Windows or macOS there is no such correspondence, so it falls back to
 * `x64`, which is what those machines are cross-building for.
 */
const TARGET_OS = process.env.TARGET_OS ?? "linux";
const TARGET_CPU =
  process.env.TARGET_CPU ?? (process.platform === "linux" ? process.arch : "x64");
const TARGET_ARGS = [`--os=${TARGET_OS}`, `--cpu=${TARGET_CPU}`];

const step = (msg) => console.log(`\n▸ ${msg}`);
const run = (cmd, args, cwd = ROOT, env = {}) =>
  execFileSync(cmd, args, {
    cwd,
    stdio: "inherit",
    shell: process.platform === "win32",
    env: { ...process.env, ...env },
  });

/*
 * Baked into the CMS bundle, because `NEXT_PUBLIC_*` is inlined into the client
 * JavaScript at build time and cannot be changed afterwards. This is precisely
 * why the build happens here rather than inside the container: the values are a
 * property of the artifact, so the artifact is what has to carry them.
 *
 * `API_SAME_ORIGIN` tells the browser the API answers on the page's own origin
 * under `/v1`, which is what `start.mjs`'s router arranges. Without it the CMS
 * appends `:4000` to whatever domain it was loaded from and every request
 * fails, login included.
 *
 * `UNOPTIMIZED_IMAGES` serves uploads as they are. Optimising needs CPU on
 * every cold image and a writable `.next/cache`, which a container running
 * under an imposed `runAsUser` does not reliably have. Nothing is lost: every
 * upload already has a WebP thumbnail generated by `sharp` at upload time.
 */
const BUILD_ENV = {
  NEXT_TELEMETRY_DISABLED: "1",
  NEXT_PUBLIC_API_SAME_ORIGIN: "true",
  NEXT_PUBLIC_UNOPTIMIZED_IMAGES: "true",
};

function dirSize(dir) {
  if (!existsSync(dir)) return 0;
  let total = 0;
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const s = statSync(full);
    total += s.isDirectory() ? dirSize(full) : s.size;
  }
  return total;
}
const mb = (bytes) => `${(bytes / 1024 / 1024).toFixed(1)} MB`;

/* ----------------------------------------------------------- dependencies */

/**
 * Install the workspace's dependencies if they are not there yet.
 *
 * The compilers — `tsc`, `nest`, `next` — are devDependencies, so a checkout
 * that has never had `npm ci` run in it fails inside the *first* workspace
 * build with `sh: 1: tsc: not found`, an npm exit code 127, and a stack trace
 * pointing at this file. Nothing in that names the missing step.
 *
 * That case is not unusual, it is the normal one: this folder is copied to a
 * build machine — a VM, a laptop, a fresh clone — and `node_modules` is the one
 * thing nobody copies, because it is 700 MB of the wrong platform's binaries.
 *
 * So the check is here rather than in a prerequisites list. It costs a
 * `existsSync` on a warm checkout and turns the failure above into a build that
 * simply works on a machine that has Node.
 */
function haveBuildTools() {
  // `typescript` compiles shared and the API; `next` builds the CMS. Both are
  // hoisted to the workspace root by npm.
  return ["typescript", "next", "@nestjs/cli"].every((pkg) =>
    existsSync(join(ROOT, "node_modules", ...pkg.split("/"))),
  );
}

if (haveBuildTools()) {
  step("Build dependencies are present");
} else {
  step("Installing build dependencies (first build on this machine)");
  console.log("  node_modules/ is missing or incomplete — this takes a few minutes, once.");

  /*
   * `npm ci` when there is a lockfile: it is faster and reproduces the exact
   * tree the application was tested against. It also *deletes* node_modules
   * first and fails outright when the lockfile and the manifests disagree —
   * which is a reasonable thing to fall back from rather than to stop on, since
   * a stale lockfile should not make the image unbuildable.
   */
  const hasLock = existsSync(join(ROOT, "package-lock.json"));
  try {
    run("npm", [hasLock ? "ci" : "install", "--no-audit", "--no-fund"], ROOT);
  } catch (error) {
    if (!hasLock) throw error;
    console.warn(`\n  ! npm ci failed (${error.message.split("\n")[0]})`);
    console.warn("    Falling back to npm install — the lockfile may be out of date.\n");
    run("npm", ["install", "--no-audit", "--no-fund"], ROOT);
  }

  if (!haveBuildTools()) {
    throw new Error(
      "the install finished but the build tools are still missing. " +
        "Check that this is the workspace root (it must have `workspaces` in " +
        "package.json) and that npm is not configured with `--omit=dev` " +
        "(`npm config get omit`).",
    );
  }
}

/* ------------------------------------------------------------------ build */

step("Cleaning previous bundle");
rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

step("Building shared, backend and frontend");
run("npm", ["run", "build"], ROOT, BUILD_ENV);

/* ---------------------------------------------------------------- backend */

step("Assembling the API");
mkdirSync(join(OUT, "backend"), { recursive: true });
cpSync(join(ROOT, "backend", "dist"), join(OUT, "backend", "dist"), { recursive: true });
cpSync(join(ROOT, "shared", "dist"), join(OUT, "shared", "dist"), { recursive: true });
cpSync(join(ROOT, "shared", "package.json"), join(OUT, "shared", "package.json"));

/*
 * Production dependencies only, installed into the bundle. `--omit=dev` drops
 * Nest's CLI, TypeScript and the test tooling, which is most of the weight and
 * none of the runtime.
 */
step("Installing production dependencies for the API");
const backendPkg = JSON.parse(
  readFileSync(join(ROOT, "backend", "package.json"), "utf8"),
);

/*
 * `@portal/shared` is dropped from the manifest before installing. It is a
 * workspace package that exists only in this repository, so a plain
 * `npm install` outside the workspace resolves it against the public registry
 * and fails with a 404. Its build output is copied into `node_modules/@portal/`
 * by hand just below, which is what the workspace symlink was doing anyway.
 */
const { "@portal/shared": _workspace, ...dependencies } = backendPkg.dependencies;

writeFileSync(
  join(OUT, "backend", "package.json"),
  JSON.stringify(
    {
      name: backendPkg.name,
      version: backendPkg.version,
      private: true,
      dependencies,
    },
    null,
    2,
  ) + "\n",
);
run(
  "npm",
  ["install", "--omit=dev", "--no-audit", "--no-fund", ...TARGET_ARGS],
  join(OUT, "backend"),
);

// `@portal/shared` is a workspace package: npm cannot resolve it from a plain
// install, so its build output is linked in by hand.
const sharedTarget = join(OUT, "backend", "node_modules", "@portal", "shared");
mkdirSync(sharedTarget, { recursive: true });
cpSync(join(ROOT, "shared", "dist"), join(sharedTarget, "dist"), { recursive: true });
cpSync(join(ROOT, "shared", "package.json"), join(sharedTarget, "package.json"));

/* ------------------------------------------------------- initial data set */

step("Bundling the initial data set");
for (const dir of ["seed-data", "seed-assets"]) {
  const from = join(ROOT, "backend", dir);
  if (!existsSync(from)) {
    console.warn(`  ! ${dir}/ is missing — run backend/scripts/export-demo-data.mjs first`);
    continue;
  }
  cpSync(from, join(OUT, "backend", dir), { recursive: true });
}

/*
 * The installation itself: every document and every uploaded file, captured
 * from the live database by `scripts/capture-live-data.mjs`.
 *
 * This is the difference between a portal that comes up as the church's actual
 * site and one that comes up empty. `restore-snapshot.mjs` fills each
 * collection only when it is empty, so this is a starting point and never a
 * reset — restarting a portal the parish has been editing changes nothing.
 *
 * `restore-snapshot.mjs` is installed inside `backend/` rather than beside the
 * entrypoint so that `mongodb` and `bson` resolve from the API's own
 * `node_modules`, which already has them via Mongoose.
 */
step("Bundling the live snapshot");
if (existsSync(join(ROOT, "snapshot", "db"))) {
  cpSync(join(ROOT, "snapshot"), join(OUT, "snapshot"), { recursive: true });
  cpSync(
    join(ROOT, "docker", "restore-snapshot.mjs"),
    join(OUT, "backend", "restore-snapshot.mjs"),
  );

  const manifestPath = join(ROOT, "snapshot", "db", "_manifest.json");
  if (existsSync(manifestPath)) {
    const m = JSON.parse(readFileSync(manifestPath, "utf8"));
    console.log(
      `  ${m.documents} documents, ${m.uploads.files} uploads, captured ${m.capturedAt}`,
    );
  }
} else {
  /*
   * Not fatal, because a bundle pointed at a database that already has content
   * is a legitimate way to deploy. Loud, because the usual cause is that the
   * capture step was skipped — and the symptom is an empty portal that looks
   * like a broken build rather than a missing input.
   */
  console.warn(
    "  ! snapshot/db is missing — this bundle will start with an EMPTY database.\n" +
      "    Capture it first, from a machine that can reach the live database:\n" +
      "        node scripts/capture-live-data.mjs",
  );
}

/* --------------------------------------------------------------- frontend */

step("Assembling the CMS");
const standalone = join(ROOT, "frontend", ".next", "standalone");
if (!existsSync(join(standalone, "frontend", "server.js"))) {
  throw new Error(
    'Standalone output missing. `output: "standalone"` must be set in frontend/next.config.ts.',
  );
}

// The standalone tree mirrors the monorepo, so its traced node_modules sit a
// level above the app.
cpSync(join(standalone, "frontend"), join(OUT, "frontend"), { recursive: true });
cpSync(join(standalone, "node_modules"), join(OUT, "node_modules"), { recursive: true });

/*
 * Next deliberately leaves these two out of the standalone trace — they are
 * served from disk rather than imported, so nothing references them. Without
 * them the CMS boots and then serves a page with no CSS or JavaScript.
 */
cpSync(join(ROOT, "frontend", ".next", "static"), join(OUT, "frontend", ".next", "static"), {
  recursive: true,
});
if (existsSync(join(ROOT, "frontend", "public"))) {
  cpSync(join(ROOT, "frontend", "public"), join(OUT, "frontend", "public"), {
    recursive: true,
  });
}

/* --------------------------------------------------- native binaries -----*/

/*
 * Replace sharp's prebuilt binaries with the target platform's.
 *
 * The API's dependencies were installed with `--os/--cpu` above, but the CMS's
 * were *copied* from the local build, so they carry whatever this machine runs.
 * Uploaded to a Linux host, Next fails on the first image it optimizes with
 * "Could not load the sharp module using the win32-x64 runtime" — and the CMS
 * looks broken for a reason nothing in the logs connects to the build machine.
 */
step(`Fetching sharp binaries for ${TARGET_OS}-${TARGET_CPU}`);

const sharpVersion = (() => {
  for (const tree of [join(OUT, "node_modules"), join(OUT, "backend", "node_modules")]) {
    const pkg = join(tree, "sharp", "package.json");
    if (existsSync(pkg)) return JSON.parse(readFileSync(pkg, "utf8")).version;
  }
  return null;
})();

if (!sharpVersion) {
  console.log("  sharp is not in the bundle — nothing to do");
} else {
  const staging = join(ROOT, ".sharp-staging");
  rmSync(staging, { recursive: true, force: true });
  mkdirSync(staging, { recursive: true });
  writeFileSync(
    join(staging, "package.json"),
    JSON.stringify({ name: "sharp-staging", private: true }, null, 2) + "\n",
  );

  /*
   * The two platform packages are named explicitly rather than installed via
   * `sharp` itself. `--os/--cpu` alone resolves only the architecture-neutral
   * parts — npm still skips the binaries, because each declares an `os`/`cpu`
   * this machine does not satisfy. Naming them and passing `--force` is what
   * actually fetches a foreign platform's binaries.
   *
   * Versions come from sharp's own `optionalDependencies`, so they always match
   * the sharp in the bundle instead of being pinned here and drifting.
   */
  const sharpPkg = JSON.parse(
    readFileSync(
      existsSync(join(OUT, "node_modules", "sharp", "package.json"))
        ? join(OUT, "node_modules", "sharp", "package.json")
        : join(OUT, "backend", "node_modules", "sharp", "package.json"),
      "utf8",
    ),
  );

  const wanted = Object.entries(sharpPkg.optionalDependencies ?? {}).filter(([name]) =>
    name.endsWith(`-${TARGET_OS}-${TARGET_CPU}`),
  );

  if (wanted.length === 0) {
    throw new Error(
      `sharp ${sharpVersion} publishes no binaries for ${TARGET_OS}-${TARGET_CPU}. ` +
        `Valid suffixes: ${Object.keys(sharpPkg.optionalDependencies ?? {}).join(", ")}`,
    );
  }

  run(
    "npm",
    [
      "install",
      ...wanted.map(([name, version]) => `${name}@${version}`),
      "--no-audit",
      "--no-fund",
      "--force",
      ...TARGET_ARGS,
    ],
    staging,
  );

  const stagedImg = join(staging, "node_modules", "@img");
  const platformDirs = existsSync(stagedImg) ? readdirSync(stagedImg) : [];

  if (platformDirs.length === 0) {
    throw new Error(`npm produced no @img binaries for ${TARGET_OS}-${TARGET_CPU}`);
  }

  for (const tree of [join(OUT, "node_modules"), join(OUT, "backend", "node_modules")]) {
    const img = join(tree, "@img");
    if (!existsSync(img)) continue;

    // Drop binaries for the build machine, keep architecture-neutral packages.
    for (const entry of readdirSync(img)) {
      if (/win32|darwin|linux|linuxmusl/.test(entry) && !entry.includes(TARGET_OS)) {
        rmSync(join(img, entry), { recursive: true, force: true });
      }
    }
    for (const dir of platformDirs) {
      cpSync(join(stagedImg, dir), join(img, dir), { recursive: true });
    }
  }

  rmSync(staging, { recursive: true, force: true });
  console.log(`  installed: ${platformDirs.join(", ")}`);
}

/* -------------------------------------------------------- strip sourcemaps */

/*
 * Source maps map the compiled API back to its TypeScript. Useful while
 * developing, and 142 files of internal structure to hand to a hosting
 * provider — they buy nothing at runtime, since nothing reads them unless a
 * debugger is attached.
 */
step("Stripping source maps");
let stripped = 0;
const dropMaps = (dir) => {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) dropMaps(full);
    else if (name.endsWith(".map")) {
      rmSync(full);
      stripped += 1;
    }
  }
};
dropMaps(join(OUT, "backend", "dist"));
dropMaps(join(OUT, "shared", "dist"));
// Next emits maps for the server bundles too — same reasoning, and they are the
// larger half.
dropMaps(join(OUT, "frontend", ".next", "server"));
console.log(`  removed ${stripped} source map(s)`);

/* ------------------------------------------------------------- entrypoint */

step("Adding the entrypoint and documentation");
cpSync(join(ROOT, "docker", "entrypoint.mjs"), join(OUT, "start.mjs"));
// The bundle's own example, not the backend's: in the bundle `PORT` is the
// public router port, while the backend's example documents it as the API's
// own — following that one puts two servers on the same number.
cpSync(join(ROOT, "docker", "bundle.env.example"), join(OUT, ".env.example"));
if (existsSync(join(ROOT, "docker", "BUNDLE-README.md"))) {
  cpSync(join(ROOT, "docker", "BUNDLE-README.md"), join(OUT, "README.md"));
}

/* ----------------------------------------------- foreign native binaries -- */

/*
 * Anything left in the bundle that only runs on the machine that built it.
 *
 * `sharp` is handled above; this catches the rest, and `@next/swc` is the one
 * that actually turns up — Next's tracer sometimes pulls the host's SWC binary
 * into the standalone tree. It is a *compiler*, so a production server never
 * loads it and the bundle works anyway, but shipping a 40 MB Windows DLL to a
 * Linux host is worth knowing about rather than discovering in an image layer.
 *
 * Removed rather than replaced: nothing at runtime asks for it.
 */
step("Removing build-machine-only native binaries");
let removedNative = 0;
for (const tree of [join(OUT, "node_modules"), join(OUT, "backend", "node_modules")]) {
  const scope = join(tree, "@next");
  if (!existsSync(scope)) continue;
  for (const entry of readdirSync(scope)) {
    // Every `@next/swc-*` goes, the target's included: it is the compiler, and
    // `next start` never loads it.
    if (!entry.startsWith("swc-")) continue;
    rmSync(join(scope, entry), { recursive: true, force: true });
    removedNative += 1;
  }
}
console.log(
  removedNative > 0
    ? `  removed ${removedNative} host-only binary package(s)`
    : "  none present",
);

/* ------------------------------------------------------------ bundle info */

/*
 * What this bundle was built by and for.
 *
 * The Dockerfile reads `node` from here so the runtime installs the *same*
 * Node the application was compiled and dependency-resolved against, rather
 * than a version pinned separately in a second file and left to drift. It reads
 * `cpu` to refuse a bundle built for the wrong architecture — an amd64 bundle
 * in an arm64 image builds cleanly and then dies on the first image operation,
 * which is a long way from the cause.
 */
step("Recording bundle metadata");
const bundleInfo = {
  name: "csistmc-portal",
  builtAt: new Date().toISOString(),
  node: process.versions.node,
  target: { os: TARGET_OS, cpu: TARGET_CPU },
  builtOn: `${process.platform}-${process.arch}`,
  sameOriginApi: true,
  snapshot: existsSync(join(OUT, "snapshot", "db", "_manifest.json"))
    ? JSON.parse(readFileSync(join(OUT, "snapshot", "db", "_manifest.json"), "utf8"))
    : null,
};
writeFileSync(join(OUT, "bundle-info.json"), JSON.stringify(bundleInfo, null, 2) + "\n");
// A bare version string as well, so a Dockerfile can `cat` it without needing
// a JSON parser in the layer that installs Node.
writeFileSync(join(OUT, ".node-version"), `${process.versions.node}\n`);
console.log(`  node ${process.versions.node}, target ${TARGET_OS}/${TARGET_CPU}`);

/* ------------------------------------------------------------------ report */

console.log("\n─────────────────────────────────────────────");
console.log("Bundle ready:", OUT);
for (const part of ["backend/dist", "backend/node_modules", "backend/seed-data", "backend/seed-assets", "snapshot", "frontend", "node_modules"]) {
  const size = dirSize(join(OUT, part));
  if (size > 0) console.log(`  ${part.padEnd(24)} ${mb(size).padStart(9)}`);
}
console.log(`  ${"TOTAL".padEnd(24)} ${mb(dirSize(OUT)).padStart(9)}`);
console.log("\nRun it with:  node start.mjs   (see README.md)");
